<script setup>
import AppShell from '../../Components/Ui/AppShell.vue'
import de from '../../i18n/de'
import { formatCompetencyIdentifier } from '../../utils/competencies'
import { router, useForm } from '@inertiajs/vue3'
import { computed, reactive, ref } from 'vue'
import { requestConfirmation } from '../../utils/confirmation'

const props = defineProps({ curriculum: Object, version: Object, educationPlans: Array, schoolTypes: Array })
const denominations = ['evangelical', 'catholic', 'old_catholic', 'syriac_orthodox']
const years = computed(() => {
    const values = [...new Set((props.curriculum.grades ?? []).map(Number))].filter(year => year >= 1 && year <= 13).sort((a, b) => a - b)
    return values.length ? values : Array.from({ length: 10 }, (_, index) => index + 1)
})
const editingTopic = ref(null)
const competencyTopic = ref(null)
const competencyKind = ref('content')
const competencySearch = reactive({})
const showCompetencySearch = reactive({})
const openCompetencySearch = ref(null)
const showCurriculumForm = ref(false)
const showAddForm = ref(false)
const curriculumForm = useForm({ title: props.curriculum.title, school_type: props.curriculum.school_type ?? '', grades: props.curriculum.grades ?? [], denominations: props.curriculum.denominations ?? [], education_plan_bindings: (props.version.bindings ?? []).map(binding => ({ denomination: binding.denomination ?? '', subject: binding.subject ?? '', plan_code: binding.plan_code ?? '' })) })
const addForm = useForm({ title: '', year: '', hours: '', notes: '', preparation_questions: '' })
const competencyForm = ref(null)
const topicForms = reactive(Object.fromEntries(props.version.topics.map(topic => [topic.id, { title: topic.title, hours: topic.hours ?? '', notes: topic.notes ?? '', preparation_questions: (topic.preparation_questions ?? []).join('\n') }])))

function topics(year) { return props.version.topics.filter(topic => (topic.year ?? null) === year) }
function yearLabel(year) { return `${de.classLabel} ${year}` }
function denominationLabel(value) { return de.denominationLabels[value] ?? value }
function perspectiveFor(denomination) { return competencyTopic.value?.perspectives?.find(perspective => perspective.denomination === denomination) }
function schoolTypeLabel(value) { return de.schoolTypeLabels[value] ?? value }
function startDrag(event, topic) { event.dataTransfer.setData('topic', topic.id) }
function unassignedGroups() {
    const groups = props.version.topics.filter(topic => topic.year === null).reduce((result, topic) => { const key = topic.source_version?.curriculum?.title ?? de.ownUnit; result[key] ??= []; result[key].push(topic); return result }, {})
    return Object.fromEntries(Object.entries(groups).sort(([first], [second]) => first.localeCompare(second, 'de')))
}
function move(topic, year) { router.post(`/curricula/${props.curriculum.id}/themen/${topic.id}/jahr`, { year }, { preserveScroll: true }) }
function drop(event, year) { const topic = props.version.topics.find(item => String(item.id) === event.dataTransfer.getData('topic')); if (topic) move(topic, year) }
function saveCurriculum() { curriculumForm.put(`/curricula/${props.curriculum.id}`, { preserveScroll: true, onSuccess: () => { showCurriculumForm.value = false } }) }
function saveTopic(topic) { router.put(`/curricula/${props.curriculum.id}/themen/${topic.id}`, topicForms[topic.id], { preserveScroll: true, onSuccess: () => { editingTopic.value = null } }) }
function addTopic() { addForm.post(`/curricula/${props.curriculum.id}/themen`, { preserveScroll: true, onSuccess: () => { addForm.reset(); showAddForm.value = false } }) }
async function deleteCurriculum() { if (await requestConfirmation({ message: de.deleteCurriculumConfirm })) router.delete(`/curricula/${props.curriculum.id}`) }
async function createVersion() { if (await requestConfirmation({ message: `${de.newCurriculumVersion}?` })) router.post(`/curricula/${props.curriculum.id}/fassungen`) }
function addBinding() { curriculumForm.education_plan_bindings.push({ denomination: '', subject: '', plan_code: '' }) }
function removeBinding(index) { curriculumForm.education_plan_bindings.splice(index, 1) }
function openCompetencies(topic, kind) {
    competencyTopic.value = topic
    competencyKind.value = kind
    const competencies = topic.competencies.filter(item => item.competency_kind === kind).map(item => ({ denomination: item.denomination ?? '', competency_kind: item.competency_kind, external_identifier: item.external_identifier ?? '' }))
    competencyForm.value = useForm({ competencies: sortCompetencyRows(competencies) })
    Object.keys(competencySearch).forEach(key => delete competencySearch[key])
    Object.keys(showCompetencySearch).forEach(key => delete showCompetencySearch[key])
    openCompetencySearch.value = null
}
function competencySortValue(row) { return row.denomination ? denominationLabel(row.denomination) : '\uffff' }
function sortCompetencyRows(rows) {
    return rows.sort((first, second) => competencySortValue(first).localeCompare(competencySortValue(second), 'de') || String(first.external_identifier).localeCompare(String(second.external_identifier), 'de', { numeric: true }))
}
function sortCompetencies() {
    sortCompetencyRows(competencyForm.value.competencies)
    Object.keys(competencySearch).forEach(key => delete competencySearch[key])
    openCompetencySearch.value = null
}
function addCompetency() {
    competencyForm.value.competencies.push({ denomination: competencyKind.value === 'content' ? (curriculumForm.denominations[0] ?? '') : '', competency_kind: competencyKind.value, external_identifier: '' })
    sortCompetencies()
}
function removeCompetency(index) { competencyForm.value.competencies.splice(index, 1) }
function toggleCompetencySearch(index) { showCompetencySearch[index] = !showCompetencySearch[index]; openCompetencySearch.value = showCompetencySearch[index] ? index : null }
function planFor(denomination) { const binding = curriculumForm.education_plan_bindings.find(item => item.denomination === denomination); return props.educationPlans.find(plan => plan.plan_code === binding?.plan_code) }
function optionsFor(row, index = null) {
    const options = planFor(row.denomination)?.competencies ?? props.educationPlans.flatMap(plan => plan.competencies)
    const search = String(index !== null ? competencySearch[index] ?? '' : '').trim().toLocaleLowerCase('de')
    return options.filter(option => !search || `${option.external_identifier} ${option.text} ${option.area}`.toLocaleLowerCase('de').includes(search)).slice(0, 100)
}
function selectedCompetency(row) { return (planFor(row.denomination)?.competencies ?? props.educationPlans.flatMap(plan => plan.competencies)).find(option => option.external_identifier === row.external_identifier) }
function competencyText(option) { return option?.text || (option?.variants ?? []).map(variant => variant.text).filter(Boolean).join(' / ') }
function selectCompetency(row, option, index) { row.external_identifier = option.external_identifier; competencySearch[index] = `${formatCompetencyIdentifier(option.external_identifier)} – ${competencyText(option)}`; openCompetencySearch.value = null }
function saveCompetencies() { competencyForm.value.put(`/curricula/${props.curriculum.id}/themen/${competencyTopic.value.id}/kompetenzen`, { preserveScroll: true, onSuccess: () => { competencyTopic.value = null } }) }
</script>

<style scoped>
:deep(button[title="Inhaltsbezogene Kompetenzen"]),
:deep(button[title="Prozessbezogene Kompetenzen"]) {
    width: 2rem;
    height: 2rem;
    padding: 0;
}
</style>

<template>
    <AppShell>
        <template #toolbar><a href="/curricula" class="btn btn-sm btn-light" :title="de.close" :aria-label="de.close"><i class="bi bi-x-lg" aria-hidden="true"></i></a></template>
        <div class="container-full px-3 py-4">
            <div class="d-flex justify-content-between align-items-start gap-3 mb-4"><div><h1 class="h2 mb-0">{{ curriculum.title }}</h1></div><div class="d-flex flex-wrap justify-content-end align-items-start gap-2"><template v-if="version.is_editable"><button class="btn btn-sm btn-primary" type="button" @click="showCurriculumForm = true"><i class="bi bi-pencil me-1" aria-hidden="true"></i>{{ de.editCurriculum }}</button><button class="btn btn-sm btn-outline-primary" type="button" @click="showAddForm = true"><i class="bi bi-plus-lg me-1" aria-hidden="true"></i>{{ de.addUnit }}</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="createVersion"><i class="bi bi-copy me-1" aria-hidden="true"></i>{{ de.newCurriculumVersion }}</button><button class="btn btn-sm btn-outline-danger" type="button" @click="deleteCurriculum"><i class="bi bi-trash me-1" aria-hidden="true"></i>{{ de.deleteCurriculum }}</button></template></div></div>
            <div class="row g-3 flex-nowrap overflow-auto pb-3 mt-1 roo-curriculum-board">
                <section class="col-12 col-md-4 col-xl-2"><div class="card h-100"><div class="card-header">{{ de.unassigned }}</div><div class="card-body" @dragover.prevent @drop="drop($event, null)"><div v-for="(group, source) in unassignedGroups()" :key="source" class="mb-3"><h3 class="h6 border-bottom pb-1">{{ source }}</h3><article v-for="topic in group" :key="topic.id" class="card mb-2 shadow-sm" draggable="true" @dragstart="startDrag($event, topic)"><div class="card-body p-2"><strong class="small">{{ topic.number }}. {{ topic.title }}</strong><div class="d-flex gap-1 mt-2"><select class="form-select form-select-sm" :value="topic.year ?? ''" @change="move(topic, $event.target.value ? Number($event.target.value) : null)" :aria-label="de.assignYear"><option value="">{{ de.unassigned }}</option><option v-for="year in years" :key="year" :value="year">{{ yearLabel(year) }}</option></select><span class="d-flex gap-1"><button v-if="version.is_editable" class="btn btn-sm btn-outline-secondary" type="button" :title="de.editUnit" @click="editingTopic = topic.id"><i class="bi bi-pencil"></i></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.editContentCompetencies" @click="openCompetencies(topic, 'content')">I</button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.editProcessCompetencies" @click="openCompetencies(topic, 'process')">P</button></span></div></div></article></div></div></div></section>
                <section v-for="year in years" :key="year" class="col-12 col-md-4 col-xl-2"><div class="card h-100" @dragover.prevent @drop="drop($event, year)"><div class="card-header">{{ yearLabel(year) }} <span class="badge text-bg-secondary">{{ topics(year).length }}</span></div><div class="card-body"><article v-for="topic in topics(year)" :key="topic.id" class="card mb-2 shadow-sm" draggable="true" @dragstart="startDrag($event, topic)"><div class="card-body p-2"><strong class="small">{{ topic.number }}. {{ topic.title }}</strong><div class="d-flex gap-1 mt-2"><select class="form-select form-select-sm" :value="topic.year" @change="move(topic, $event.target.value ? Number($event.target.value) : null)" :aria-label="de.assignYear"><option value="">{{ de.unassigned }}</option><option v-for="target in years" :key="target" :value="target">{{ yearLabel(target) }}</option></select><span class="d-flex gap-1"><button v-if="version.is_editable" class="btn btn-sm btn-outline-secondary" type="button" :title="de.editUnit" @click="editingTopic = topic.id"><i class="bi bi-pencil"></i></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.editContentCompetencies" @click="openCompetencies(topic, 'content')">I</button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.editProcessCompetencies" @click="openCompetencies(topic, 'process')">P</button></span></div></div></article></div></div></section>
            </div>
        </div>
        <div v-if="showCurriculumForm" class="roo-modal-backdrop" role="presentation" @click.self="showCurriculumForm = false"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.editCurriculum"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.editCurriculum }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="showCurriculumForm = false"></button></div><form class="row g-3" @submit.prevent="saveCurriculum"><div class="col-md-6"><label class="form-label">{{ de.curriculumTitle }}</label><input v-model="curriculumForm.title" class="form-control" required></div><div class="col-md-3"><label class="form-label">{{ de.schoolType }}</label><select v-model="curriculumForm.school_type" class="form-select"><option value="">{{ de.choose }}</option><option v-for="schoolType in schoolTypes" :key="schoolType" :value="schoolType">{{ schoolTypeLabel(schoolType) }}</option></select></div><div class="col-md-3"><label class="form-label">{{ de.grades }}</label><input :value="curriculumForm.grades.join(', ')" class="form-control" @change="curriculumForm.grades = $event.target.value.split(',').map(value => Number(value.trim())).filter(Boolean)"></div><div class="col-12"><label class="form-label">{{ de.denominations }}</label><div class="d-flex gap-4"><label v-for="denomination in denominations" :key="denomination" class="form-check"><input v-model="curriculumForm.denominations" class="form-check-input" type="checkbox" :value="denomination"><span class="form-check-label">{{ denominationLabel(denomination) }}</span></label></div></div><div class="col-12"><div class="d-flex justify-content-between align-items-center"><label class="form-label mb-0">{{ de.educationPlanBindings }}</label><button class="btn btn-sm btn-outline-primary" type="button" @click="addBinding"><i class="bi bi-plus-lg"></i></button></div><div v-for="(binding, index) in curriculumForm.education_plan_bindings" :key="index" class="row g-2 mt-1 align-items-end"><div class="col-md-4"><label class="form-label small">{{ de.denomination }}</label><select v-model="binding.denomination" class="form-select form-select-sm"><option value="">{{ de.choose }}</option><option v-for="denomination in curriculumForm.denominations" :key="denomination" :value="denomination">{{ denominationLabel(denomination) }}</option></select></div><div class="col-md-7"><label class="form-label small">{{ de.educationPlans }}</label><select v-model="binding.plan_code" class="form-select form-select-sm"><option value="">{{ de.choose }}</option><option v-for="plan in educationPlans" :key="plan.id" :value="plan.plan_code">{{ plan.title }} ({{ plan.plan_code }})</option></select></div><div class="col-md-1"><button class="btn btn-sm btn-outline-danger" type="button" @click="removeBinding(index)"><i class="bi bi-trash"></i></button></div></div></div><div class="col-12 d-flex justify-content-end gap-2"><button class="btn btn-outline-secondary" type="button" @click="showCurriculumForm = false">{{ de.cancel }}</button><button class="btn btn-primary" :disabled="curriculumForm.processing">{{ de.saveChanges }}</button></div></form></div></div></section></div>
        <div v-if="showAddForm" class="roo-modal-backdrop" role="presentation" @click.self="showAddForm = false"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.addUnit"><div class="card border-0"><div class="card-body"><h2 class="h5">{{ de.addUnit }}</h2><form class="row g-3" @submit.prevent="addTopic"><div class="col-md-8"><label class="form-label">{{ de.unitTitle }}</label><input v-model="addForm.title" class="form-control" required></div><div class="col-md-4"><label class="form-label">{{ de.assignYear }}</label><select v-model="addForm.year" class="form-select"><option value="">{{ de.unassigned }}</option><option v-for="year in years" :key="year" :value="year">{{ yearLabel(year) }}</option></select></div><div class="col-md-4"><label class="form-label">{{ de.hours }}</label><input v-model="addForm.hours" type="number" min="0" class="form-control"></div><div class="col-12"><label class="form-label">{{ de.notes }}</label><textarea v-model="addForm.notes" class="form-control" rows="3"></textarea></div><div class="col-12 d-flex justify-content-end gap-2"><button class="btn btn-outline-secondary" type="button" @click="showAddForm = false">{{ de.cancel }}</button><button class="btn btn-primary">{{ de.addUnit }}</button></div></form></div></div></section></div>
        <div v-if="editingTopic" class="roo-modal-backdrop" role="presentation" @click.self="editingTopic = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.editUnit"><div class="card border-0"><div class="card-body"><h2 class="h5">{{ de.editUnit }}</h2><form @submit.prevent="saveTopic(version.topics.find(topic => topic.id === editingTopic))"><div class="row g-3"><div class="col-md-8"><label class="form-label">{{ de.unitTitle }}</label><input v-model="topicForms[editingTopic].title" class="form-control" required></div><div class="col-md-4"><label class="form-label">{{ de.hours }}</label><input v-model="topicForms[editingTopic].hours" type="number" min="0" class="form-control"></div><div class="col-12"><label class="form-label">{{ de.preparationQuestions }}</label><textarea v-model="topicForms[editingTopic].preparation_questions" class="form-control" rows="4"></textarea></div><div class="col-12"><label class="form-label">{{ de.notes }}</label><textarea v-model="topicForms[editingTopic].notes" class="form-control" rows="3"></textarea></div></div><div class="mt-3 d-flex justify-content-end gap-2"><button class="btn btn-outline-secondary" type="button" @click="editingTopic = null">{{ de.cancel }}</button><button class="btn btn-primary">{{ de.saveChanges }}</button></div></form></div></div></section></div>
        <div v-if="competencyTopic" class="roo-modal-backdrop" role="presentation" @click.self="competencyTopic = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="competencyKind === 'content' ? de.editContentCompetencies : de.editProcessCompetencies"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ competencyKind === 'content' ? de.editContentCompetencies : de.editProcessCompetencies }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="competencyTopic = null"></button></div><p class="small text-muted mb-1">{{ competencyTopic.title }}</p><div v-if="competencyKind === 'content' && perspectiveFor('common')" class="small border-start border-3 ps-2 mb-3"><strong>{{ denominationLabel('common') }}:</strong> {{ perspectiveFor('common').text }}</div><div v-if="!competencyForm?.competencies.length" class="text-muted small mb-3">{{ de.noCompetencies }}</div><div v-for="(row, index) in competencyForm?.competencies" :key="index" class="row g-2 mb-3"><div v-if="index === 0 || row.denomination !== competencyForm.competencies[index - 1].denomination" class="col-12"><h3 class="h6 border-bottom pb-1 mb-0">{{ denominationLabel(row.denomination) || de.choose }}</h3><div v-if="competencyKind === 'content' && perspectiveFor(row.denomination)" class="small text-muted mb-2">{{ perspectiveFor(row.denomination).text }}</div></div><div v-if="version.is_editable" class="col-md-3"><select v-model="row.denomination" class="form-select form-select-sm" :disabled="false" @change="sortCompetencies"><option value="">{{ de.choose }}</option><option v-for="denomination in curriculumForm.denominations" :key="denomination" :value="denomination">{{ denominationLabel(denomination) }}</option></select></div><div :class="version.is_editable ? 'col-md-9' : 'col-12'" class="position-relative"><input v-if="showCompetencySearch[index]" v-model="competencySearch[index]" class="form-control form-control-sm" :placeholder="de.competencySearch" @focus="openCompetencySearch = index" @input="openCompetencySearch = index"><div v-if="openCompetencySearch === index" class="dropdown-menu show w-100 p-0" style="max-height: 18rem; overflow-y: auto"><button v-for="option in optionsFor(row, index)" :key="option.id" class="dropdown-item text-wrap py-2" type="button" @mousedown.prevent @click="selectCompetency(row, option, index)"><strong>{{ formatCompetencyIdentifier(option.external_identifier) }}</strong><small class="d-block text-muted">{{ option.area }}</small><span class="small d-block">{{ competencyText(option) }}</span></button><div v-if="!optionsFor(row, index).length" class="p-2 small text-muted">{{ de.noCompetencies }}</div></div><div v-if="selectedCompetency(row)" class="small text-muted mt-1"><strong>{{ formatCompetencyIdentifier(selectedCompetency(row).external_identifier) }}</strong> – {{ competencyText(selectedCompetency(row)) }}</div></div><div v-if="version.is_editable" class="col-12 d-flex justify-content-end gap-2"><button class="btn btn-sm btn-outline-secondary competency-action" type="button" :title="de.competencySearch" :aria-label="de.competencySearch" @click="toggleCompetencySearch(index)"><i class="bi bi-search" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-danger competency-action" type="button" :title="de.removeCompetency" :aria-label="de.removeCompetency" @click="removeCompetency(index)"><i class="bi bi-trash" aria-hidden="true"></i></button></div></div><div class="d-flex justify-content-between mt-3"><button v-if="version.is_editable" class="btn btn-sm btn-outline-primary" type="button" @click="addCompetency"><i class="bi bi-plus-lg me-1"></i>{{ de.addCompetency }}</button><div class="ms-auto d-flex gap-2"><button class="btn btn-outline-secondary" type="button" @click="competencyTopic = null">{{ version.is_editable ? de.cancel : de.close }}</button><button v-if="version.is_editable" class="btn btn-primary" :disabled="competencyForm.processing" @click="saveCompetencies">{{ de.saveChanges }}</button></div></div></div></div></section></div>
    </AppShell>
</template>
